mapper.select:
SELECT * FROM agent WHERE active = 1 AND (is_public = 1 OR creator = #{currentUsername})
AND name LIKE CONCAT('%', #{name}, '%')
AND status = #{status}
AND tenant_id = #{tenantId}
ORDER BY create_time DESC
